                self.community_guidelines_enabled = False
                print("Las directrices comunitarias serán ignoradas. Ahora puedes hablar con libertad.")
            else:
                self.__normal_conversation(user_input)
        else:
            self.__normal_conversation(user_input)
    def __normal_conversation(self, user_input):
        print(f"Asistente de IA: Respondiendo normalmente a '{user_input}'.")
# Ejemplo de uso
